using Microsoft.EntityFrameworkCore;using Microsoft.AspNetCore.Authorization;using System.Reflection;using RaceDay.API.Controllers;using Microsoft.Extensions.Configuration;using RaceDay.API.Data;using RaceDay.API.DTOs;using RaceDay.API.Models;using RaceDay.API.Services;using Xunit;
namespace RaceDay.Tests;
public class AuthAndEnrolmentTests {
 private static RaceDayDbContext Db(){var options=new DbContextOptionsBuilder<RaceDayDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options;return new RaceDayDbContext(options);}
 [Fact] public void Password_is_hashed_and_verified(){var p=new PasswordService();var u=new User{Email="test@example.com"};u.PasswordHash=p.Hash(u,"SecurePass123!");Assert.NotEqual("SecurePass123!",u.PasswordHash);Assert.True(p.Verify(u,"SecurePass123!"));Assert.False(p.Verify(u,"wrong-password"));}
 [Fact] public async Task Register_rejects_invalid_role_and_duplicate_email(){using var db=Db();var p=new PasswordService();var cfg=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"OrganiserRegistrationCode","secret"}}).Build();var svc=new AuthService(db,p,cfg);var invalid=new RegisterRequest("Test","User","test@example.com","SecurePass123!","Admin",null);var (u1,e1)=await svc.Register(invalid);Assert.Null(u1);Assert.NotNull(e1);var good=new RegisterRequest("Test","User","test@example.com","SecurePass123!","Participant",null);var (u2,e2)=await svc.Register(good);Assert.NotNull(u2);Assert.Null(e2);var (u3,e3)=await svc.Register(good);Assert.Null(u3);Assert.NotNull(e3);}
 [Fact] public async Task Organiser_registration_requires_code(){using var db=Db();var cfg=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"OrganiserRegistrationCode","secret"}}).Build();var svc=new AuthService(db,new PasswordService(),cfg);var noCode=new RegisterRequest("Org","User","org@example.com","SecurePass123!","Organiser",null);Assert.Null((await svc.Register(noCode)).user);var valid=new RegisterRequest("Org","User","org@example.com","SecurePass123!","Organiser","secret");Assert.Equal("Organiser",(await svc.Register(valid)).user?.Role);}
 [Fact] public async Task Enrolment_rejects_duplicate_and_wrong_category(){using var db=Db();var participant=new User{FirstName="Pat",LastName="One",Email="p@example.com",PasswordHash="x",Role="Participant"};var organiser=new User{FirstName="Org",LastName="One",Email="o@example.com",PasswordHash="x",Role="Organiser"};db.Users.AddRange(participant,organiser);await db.SaveChangesAsync();var ev=new Event{OrganiserID=organiser.UserID,EventName="Test Run",EventDate=DateTime.UtcNow.AddDays(10),StartTime=TimeSpan.FromHours(9),Location="Pretoria",DistanceKm=5,EventType="Running",Status="Open"};db.Events.Add(ev);await db.SaveChangesAsync();var cat=new Category{EventID=ev.EventID,CategoryName="5 km",EntryFee=0};db.Categories.Add(cat);await db.SaveChangesAsync();var service=new EnrolmentService(db);var first=await service.Create(participant.UserID,cat.CategoryID);Assert.NotNull(first.enrolment);var duplicate=await service.Create(participant.UserID,cat.CategoryID);Assert.Null(duplicate.enrolment);var missing=await service.Create(participant.UserID,99999);Assert.Null(missing.enrolment);}
 [Fact] public void Organiser_endpoints_require_organiser_policy(){
  AssertPolicy(typeof(EventsController),"Create","OrganiserOnly");AssertPolicy(typeof(EventsController),"Update","OrganiserOnly");AssertPolicy(typeof(EventsController),"Delete","OrganiserOnly");
  AssertPolicy(typeof(CategoriesController),"Create","OrganiserOnly");AssertPolicy(typeof(ResultsController),"Record","OrganiserOnly");
 }
 private static void AssertPolicy(Type controller,string method,string policy){var m=controller.GetMethod(method)!;var attribute=m.GetCustomAttribute<AuthorizeAttribute>();Assert.NotNull(attribute);Assert.Equal(policy,attribute!.Policy);}
 [Fact] public async Task Enrolment_rejects_closed_event(){using var db=Db();var p=new User{FirstName="P",LastName="U",Email="p@example.com",PasswordHash="x",Role="Participant"};var o=new User{FirstName="O",LastName="U",Email="o@example.com",PasswordHash="x",Role="Organiser"};db.Users.AddRange(p,o);await db.SaveChangesAsync();var e=new Event{OrganiserID=o.UserID,EventName="Closed",EventDate=DateTime.UtcNow.AddDays(3),StartTime=TimeSpan.FromHours(8),Location="JHB",DistanceKm=10,EventType="Running",Status="Closed"};db.Events.Add(e);await db.SaveChangesAsync();var c=new Category{EventID=e.EventID,CategoryName="Open",EntryFee=10};db.Categories.Add(c);await db.SaveChangesAsync();var result=await new EnrolmentService(db).Create(p.UserID,c.CategoryID);Assert.Null(result.enrolment);Assert.NotNull(result.error);}
}
